// goStr converts a callback-owned C string to Go and frees it.
func goStr(p *C.char) string {
	if p == nil {
		return ""
	}
	s := C.GoString(p)
	C.free(unsafe.Pointer(p))
	return s
}

func strErr(s string) error {
	if s == "" {
		return nil
	}
	return errors.New(s)
}

func mustJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// splitJSONStrings decodes a JSON string array.
func splitJSONStrings(s string) []string {
	var out []string
	if json.Unmarshal([]byte(s), &out) != nil {
		return nil
	}
	return out
}

// parseConnectionOwner / parseWIFIState / parseNetworkInterfaces decode the JSON
// the JNI shim returns for object-shaped callbacks.
func parseConnectionOwner(js string) (*ConnectionOwner, error) {
	var dto struct {
		UserId       int32    `json:"userId"`
		UserName     string   `json:"userName"`
		ProcessPath  string   `json:"processPath"`
		PackageNames []string `json:"packageNames"`
	}
	if err := json.Unmarshal([]byte(js), &dto); err != nil {
		return nil, err
	}
	c := &ConnectionOwner{UserId: dto.UserId, UserName: dto.UserName, ProcessPath: dto.ProcessPath}
	c.SetAndroidPackageNames(newIterator(dto.PackageNames))
	return c, nil
}

func parseWIFIState(js string) *WIFIState {
	var dto struct {
		SSID  string `json:"ssid"`
		BSSID string `json:"bssid"`
	}
	if json.Unmarshal([]byte(js), &dto) != nil {
		return nil
	}
	return NewWIFIState(dto.SSID, dto.BSSID)
}

func parseNetworkInterfaces(js string) NetworkInterfaceIterator {
	var dtos []struct {
		Index     int32    `json:"index"`
		MTU       int32    `json:"mtu"`
		Name      string   `json:"name"`
		Addresses []string `json:"addresses"`
		Flags     int32    `json:"flags"`
		Type      int32    `json:"type"`
		DNSServer []string `json:"dnsServer"`
		Gateway   []string `json:"gateway"`
		Metered   bool     `json:"metered"`
	}
	if json.Unmarshal([]byte(js), &dtos) != nil {
		return newIterator([]*NetworkInterface(nil))
	}
	out := make([]*NetworkInterface, 0, len(dtos))
	for _, d := range dtos {
		out = append(out, &NetworkInterface{
			Index: d.Index, MTU: d.MTU, Name: d.Name, Flags: d.Flags,
			Type: d.Type, Metered: d.Metered,
			Addresses: newIterator(d.Addresses),
			DNSServer: newIterator(d.DNSServer),
			Gateway:   newIterator(d.Gateway),
		})
	}
	return newIterator(out)
}

// lastInstance lets throne_suspend reach the running box.
var lastInstance struct {
	mu   sync.Mutex
	inst *Instance
}

// registerInstance is called from the generated Instance constructor.
func registerInstance(i *Instance) {
	lastInstance.mu.Lock()
	lastInstance.inst = i
	lastInstance.mu.Unlock()
}

// clearInstance drops the process-wide reference when the box it names is
// closed. Without this lastInstance.inst kept pointing at a closed box for the
// rest of the process, and anything reading it (throne_suspend, the speed/IP
// test fallbacks) could act on a dead instance.
func clearInstance(i *Instance) {
	lastInstance.mu.Lock()
	if lastInstance.inst == i {
		lastInstance.inst = nil
	}
	lastInstance.mu.Unlock()
}

// startIPTestLive measures the current core through its proxy outbound when the
// request carries no probe config. StartIPTest otherwise builds a separate box,
// which reports the device/Wi-Fi exit on Android instead of the running proxy's.
func startIPTestLive(platform PlatformInterface, request *TestRequest, handler IPTestHandler) error {
	if request == nil || handler == nil {
		return errors.New("nil request or handler")
	}
	if request.CoreConfig != "" {
		return StartIPTest(platform, request, handler)
	}
	lastInstance.mu.Lock()
	current := lastInstance.inst
	lastInstance.mu.Unlock()
	if current == nil || !current.running() {
		return errInstanceNotRunning
	}
	env, err := prepareTestEnv(current, true, platform, request)
	if err != nil {
		return err
	}
	testCtx := probe.LiveInstance(probe.TestContext())
	timeout := time.Duration(request.TimeoutMs) * time.Millisecond
	go func() {
		defer handler.OnDone()
		defer env.Close()
		newTestReporter(env.Tags, probe.IPReporter.Results,
			func(result *probe.IPTestResult) string { return result.Tag },
			func(result *probe.IPTestResult) {
				handler.OnResult(result.Tag, result.Result.IP, result.Result.CountryCode, errorString(result.Error))
			},
		).run(func() []*probe.IPTestResult {
			// "" = auto provider: the live-IP path has no explicit exit_lookup_provider id.
			return probe.BatchIPTest(testCtx, env.Box, env.Tags, int(request.MaxConcurrency), false, timeout, "")
		})
	}()
	return nil
}

// startURLTestLive is the one URL-test entry point. When TestCurrent is set it resolves the live instance in this
// process even if the caller could not carry its handle across a service boundary, then measures the actual exit.
// Probe tests stay available for offline nodes, but they run one request like FlClash instead of a warm-up plus a
// second timed request; a slow or muxed node therefore cannot be failed by the probe's extra round trip.
func startURLTestLive(currentHandle int64, platform PlatformInterface, request *TestRequest, handler URLTestHandler) error {
	if request == nil || handler == nil {
		return errors.New("nil request or handler")
	}
	var current *Instance
	if request.TestCurrent {
		if currentHandle != 0 {
			if value, ok := handleGet(currentHandle).(*Instance); ok {
				current = value
			}
		}
		if current == nil || !current.running() {
			lastInstance.mu.Lock()
			latest := lastInstance.inst
			lastInstance.mu.Unlock()
			if latest != nil && latest.running() {
				current = latest
			}
		}
	}
	env, err := prepareTestEnv(current, request.TestCurrent, platform, request)
	if err != nil {
		return err
	}
	testCtx := probe.TestContext()
	if request.TestCurrent {
		testCtx = probe.LiveInstance(testCtx)
	}
	timeout := time.Duration(request.TimeoutMs) * time.Millisecond
	go func() {
		defer handler.OnDone()
		defer env.Close()
		failed := make(map[string]bool, len(env.Tags))
		newTestReporter(env.Tags, probe.URLReporter.Results,
			func(result *probe.URLTestResult) string { return result.Tag },
			func(result *probe.URLTestResult) {
				failed[result.Tag] = result.Error != nil
				handler.OnResult(result.Tag, int32(result.Duration.Milliseconds()), errorString(result.Error))
			},
		).run(func() []*probe.URLTestResult {
			return probe.BatchURLTest(testCtx, env.Box, env.Tags, request.URL, int(request.MaxConcurrency), false, timeout)
		})
		for _, tag := range request.vpnEndpointTags {
			if failed[tag] {
				connected, state, err := vpnEndpointVerdict(env.Box, tag)
				handler.OnVPNStatus(tag, connected, state, err)
			}
		}
	}()
	return nil
}

// --- tun options for VpnService.Builder ------------------------------------

//export throne_getAndroidVpnOptions
func throne_getAndroidVpnOptions(coreConfig *C.char) *C.char {
	defer guardExport("throne_getAndroidVpnOptions")
	var raw map[string]interface{}
	if json.Unmarshal([]byte(C.GoString(coreConfig)), &raw) != nil {
		return C.CString("{}")
	}
	inbounds, _ := raw["inbounds"].([]interface{})
	for _, ib := range inbounds {
		m, _ := ib.(map[string]interface{})
		if m != nil && m["type"] == "tun" {
			b, _ := json.Marshal(m)
			return C.CString(string(b))
		}
	}
	return C.CString("{}")
}

// handleRelease drops a temp handle created for a callback crossing.
func handleRelease(h int64) {
	handlesMu.Lock()
	defer handlesMu.Unlock()
	delete(handles, h)
}

//export throne_TunOptions_toJSON
func throne_TunOptions_toJSON(handle C.int64_t) *C.char {
	defer guardExport("throne_TunOptions_toJSON")
	o, _ := handleGet(int64(handle)).(TunOptions)
	if o == nil {
		return C.CString("")
	}
	prefixes := func(it RoutePrefixIterator) []map[string]interface{} {
		out := make([]map[string]interface{}, 0, 4)
		for it != nil && it.HasNext() {
			p := it.Next()
			out = append(out, map[string]interface{}{"address": p.Address(), "prefix": p.Prefix()})
		}
		return out
	}
	stringsOf := func(it StringIterator) []string {
		out := make([]string, 0, 4)
		for it != nil && it.HasNext() {
			out = append(out, it.Next())
		}
		return out
	}
	dto := map[string]interface{}{}
	dto["mtu"] = o.GetMTU()
	dto["autoRoute"] = o.GetAutoRoute()
	dto["strictRoute"] = o.GetStrictRoute()
	dto["inet4Address"] = prefixes(o.GetInet4Address())
	dto["inet6Address"] = prefixes(o.GetInet6Address())
	dto["inet4RouteAddress"] = prefixes(o.GetInet4RouteAddress())
	dto["inet6RouteAddress"] = prefixes(o.GetInet6RouteAddress())
	dto["inet4RouteExcludeAddress"] = prefixes(o.GetInet4RouteExcludeAddress())
	dto["inet6RouteExcludeAddress"] = prefixes(o.GetInet6RouteExcludeAddress())
	dto["inet4RouteRange"] = prefixes(o.GetInet4RouteRange())
	dto["inet6RouteRange"] = prefixes(o.GetInet6RouteRange())
	dto["includePackage"] = stringsOf(o.GetIncludePackage())
	dto["excludePackage"] = stringsOf(o.GetExcludePackage())
	// HTTPProxy is a pointer in TunPlatformOptions and stays nil whenever the
	// option is off. GetHTTPProxyServer/Port/BypassDomain dereference it without
	// a guard, so calling them unconditionally panics the whole marshaling — the
	// tun spec arrives empty and every start dies in VpnService.Builder with
	// "End of input at character 0". Read them only when they exist.
	if httpProxy := o.IsHTTPProxyEnabled(); httpProxy {
		dto["httpProxyEnabled"] = true
		dto["httpProxyServer"] = o.GetHTTPProxyServer()
		dto["httpProxyServerPort"] = o.GetHTTPProxyServerPort()
		dto["httpProxyBypassDomain"] = stringsOf(o.GetHTTPProxyBypassDomain())
	} else {
		dto["httpProxyEnabled"] = false
		dto["httpProxyServer"] = ""
		dto["httpProxyServerPort"] = int32(0)
		dto["httpProxyBypassDomain"] = []string{}
	}
	if mode := o.GetDNSMode(); mode != nil {
		dto["dnsMode"] = mode.Value
	}
	if dns, err := o.GetDNSServerAddress(); err == nil {
		dto["dnsServerAddress"] = stringsOf(dns)
	}
	b, _ := json.Marshal(dto)
	return C.CString(string(b))
}

var _ = unsafe.Pointer(nil)
